catalog_script_client.script:
function onSubmit() {
    try {
        // Replace 'menu_items' with your actual MRVS variable name
        var mrvsValue = g_form.getValue('menu_items');

        if (!mrvsValue || mrvsValue.trim() === "") {
            console.log("MRVS is empty");
            return true;
        }

        var rows = JSON.parse(mrvsValue);
        var total = 0;

        for (var i = 0; i < rows.length; i++) {
            var priceStr = rows[i].food_price; // Replace with your field name if different

            if (priceStr) {
                var price = parseFloat(priceStr.trim());
                if (!isNaN(price)) {
                    total += price;
                }
            }
        }

        // Debug (optional): Show result
        alert("Total: " + total.toFixed(2));
        var userConfirmed = confirm("Total: ₹" + total.toFixed(2) + "\nDo you want to proceed with the order?");

        if (userConfirmed) {
            // User clicked OK (Yes)
            g_form.setValue('total_price', total.toFixed(2));
        } else {
            // User clicked Cancel (No)
            console.log("User chose not to proceed.");
            return false; // Prevent form submission
        }

    } catch (e) {
        console.log("Error: " + e.message);
    }

    return true;
}
